insert into public.englishsuccess_curriculum_skills(id,level,position,payload)
select v->>'id',v->>'level',(v->>'order')::integer,v from jsonb_array_elements('[{"id":"participants","level":"A1","order":0,"title":"Who acts; who receives","family":"pronouns","thaiBridge":"Thai pronouns often retain their form across roles. English marks I/me, she/her, we/us and they/them. Test the role, not the gender.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":6,"englishPrerequisites":["past-events"]},{"id":"be-forms","level":"A1","order":1,"title":"Matching be to the subject","family":"verbs","thaiBridge":"Thai descriptions may not require an equivalent of be. English requires am/is/are with these subjects.","prerequisites":["participants"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":2,"englishPrerequisites":["first-actions","first-negatives"]},{"id":"reference","level":"A1","order":2,"title":"One, several, this, that","family":"determiners","thaiBridge":"Thai does not have an article system equivalent to English. Use a clear referent and number; do not translate the as a fixed Thai word.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":3,"englishPrerequisites":["first-actions","first-negatives"]},{"id":"ownership","level":"A1","order":3,"title":"Owner and possession","family":"pronouns","thaiBridge":"Thai can use khong + owner. English distinguishes my/mine and her/hers by their place in the phrase.","prerequisites":["participants","reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":7,"englishPrerequisites":["participants","reference","first-actions","first-negatives"]},{"id":"routine-now","level":"A1","order":4,"title":"Routine versus happening now","family":"verbs","thaiBridge":"Gam lang can signal an ongoing event. Contrast an English routine with be + -ing while keeping the action identical.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":4,"englishPrerequisites":["be-forms","first-actions","first-negatives"]},{"id":"past-state","level":"A1","order":5,"title":"Current and earlier states","family":"verbs","thaiBridge":"Thai uses context and time expressions; English changes is/are to was/were.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":8,"englishPrerequisites":["be-forms","first-actions","first-negatives"]},{"id":"negation","level":"A1","order":6,"title":"Positive and negative","family":"verbs","thaiBridge":"Mai does not map to one fixed English form. Contrast not with be and do-support with lexical verbs.","prerequisites":["be-forms"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":9,"englishPrerequisites":["be-forms","first-actions","first-negatives"]},{"id":"questions","level":"A1","order":7,"title":"Asking and answering","family":"verbs","thaiBridge":"Thai question particles do not move the verb. English may need be inversion or do/does before the subject.","prerequisites":["be-forms","negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":10,"englishPrerequisites":["be-forms","negation","first-actions","first-negatives"]},{"id":"time-place","level":"A1","order":8,"title":"Location and time relations","family":"relationships","thaiBridge":"Thai relational words do not map one-to-one to English prepositions. Keep locations and events constant between choices.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":11,"englishPrerequisites":["first-actions","first-negatives"]},{"id":"simple-links","level":"A1","order":9,"title":"Add, contrast, explain","family":"relationships","thaiBridge":"Lae, tae and phro help introduce the meaning of and, but and because. Both choices must not be equally defensible.","prerequisites":["negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":12,"englishPrerequisites":["negation","first-actions","first-negatives"]},{"id":"past-events","level":"A1","order":10,"title":"Finished events","family":"verbs","thaiBridge":"Laew is not a universal past-tense marker. Contrast a finished event with a routine, using the same action.","prerequisites":["routine-now"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":5,"englishPrerequisites":["routine-now","first-actions","first-negatives"]},{"id":"request-basics","level":"A1","order":11,"title":"Ask politely; give directions","family":"interaction","thaiBridge":"English requests rely on modal and sentence choices, not an equivalent of khrap/kha appended to every sentence.","prerequisites":["questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":13,"englishPrerequisites":["questions","first-actions","first-negatives"]},{"id":"future","level":"A2","order":12,"title":"Plans and upcoming actions","family":"verbs","thaiBridge":"Ja introduces future or intended events in many contexts. English distinguishes will, going to and present arrangements.","prerequisites":["routine-now"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":14,"englishPrerequisites":["routine-now","first-actions","first-negatives"]},{"id":"completion","level":"A2","order":13,"title":"In progress versus completed","family":"verbs","thaiBridge":"Gam lang and laew provide a starting contrast, not a complete equivalence to continuous and perfect forms.","prerequisites":["routine-now","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":15,"englishPrerequisites":["routine-now","past-events","first-actions","first-negatives"]},{"id":"verb-shapes","level":"A2","order":14,"title":"Verb forms after helpers","family":"verbs","thaiBridge":"English auxiliaries determine the following verb form; Thai verbs do not take these same endings.","prerequisites":["completion","questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":16,"englishPrerequisites":["completion","questions","first-actions","first-negatives"]},{"id":"obligation","level":"A2","order":15,"title":"Ability, permission, obligation","family":"verbs","thaiBridge":"Dai and tong can help establish the distinction, but cannot be substituted mechanically for every can or must.","prerequisites":["negation"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":17,"englishPrerequisites":["negation","first-actions","first-negatives"]},{"id":"verb-complements","level":"A2","order":16,"title":"What follows a verb","family":"verbs","thaiBridge":"Learn whole patterns such as ask someone to wait and want to leave; not an isolated translation of to.","prerequisites":["participants","verb-shapes"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":18,"englishPrerequisites":["participants","verb-shapes","first-actions","first-negatives"]},{"id":"quantity","level":"A2","order":17,"title":"Amounts and countability","family":"determiners","thaiBridge":"Thai classifiers and English articles/countability divide the work differently. Use the same object and clear quantity evidence.","prerequisites":["reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":19,"englishPrerequisites":["reference","first-actions","first-negatives"]},{"id":"sequence","level":"A2","order":18,"title":"Order events and conditions","family":"relationships","thaiBridge":"Use Thai to disambiguate before, after and if while holding the events stable.","prerequisites":["time-place","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":20,"englishPrerequisites":["time-place","past-events","first-actions","first-negatives"]},{"id":"comparison","level":"A2","order":19,"title":"Compare choices","family":"relationships","thaiBridge":"Kwa helps introduce comparison. English also changes adjectives or uses more; test the relation, not different objects.","prerequisites":["reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":21,"englishPrerequisites":["reference","first-actions","first-negatives"]},{"id":"repair","level":"B1","order":20,"title":"Clarify a misunderstanding","family":"interaction","thaiBridge":"Practise checking the intended meaning rather than choosing a response by a recognised noun.","prerequisites":["request-basics","questions"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":22,"englishPrerequisites":["request-basics","questions","first-actions","first-negatives"]},{"id":"past-sequence","level":"B1","order":21,"title":"Earlier than another past event","family":"verbs","thaiBridge":"Explicit Thai event order supports English past-perfect contrasts without pretending laew alone identifies the tense.","prerequisites":["completion","sequence"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":23,"englishPrerequisites":["completion","sequence","first-actions","first-negatives"]},{"id":"passive","level":"B1","order":22,"title":"Action and affected person","family":"verbs","thaiBridge":"Thai thuk/dai rap may help in some contexts. English passive changes focus and requires be plus a participle.","prerequisites":["participants","verb-shapes"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":24,"englishPrerequisites":["participants","verb-shapes","first-actions","first-negatives"]},{"id":"possibility","level":"B1","order":23,"title":"Certainty and possibility","family":"verbs","thaiBridge":"Thai uncertainty expressions support the meaning; English modals and their forms distinguish confidence and time.","prerequisites":["obligation","future"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":25,"englishPrerequisites":["obligation","future","first-actions","first-negatives"]},{"id":"reported","level":"B1","order":24,"title":"Report someone’s message","family":"verbs","thaiBridge":"Keep the speaker and event fixed while testing English changes in reference and reported time.","prerequisites":["past-sequence","participants"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":26,"englishPrerequisites":["past-sequence","participants","first-actions","first-negatives"]},{"id":"hypothetical","level":"B1","order":25,"title":"Imagine a different situation","family":"relationships","thaiBridge":"Thai tha does not require the same English tense pattern in hypothetical conditions.","prerequisites":["sequence","past-events"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":27,"englishPrerequisites":["sequence","past-events","first-actions","first-negatives"]},{"id":"relative","level":"B2","order":26,"title":"Identify which person or thing","family":"relationships","thaiBridge":"Thai thi is a bridge to some relative clauses, not a one-to-one translation of who, which and that.","prerequisites":["participants","reference"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":28,"englishPrerequisites":["participants","reference","first-actions","first-negatives"]},{"id":"future-completion","level":"B2","order":27,"title":"Completed by a future point","family":"verbs","thaiBridge":"Hold the deadline and action constant; test whether English describes progress or completion at that point.","prerequisites":["completion","future"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":29,"englishPrerequisites":["completion","future","first-actions","first-negatives"]},{"id":"counterfactual","level":"B2","order":28,"title":"Unreal causes and consequences","family":"relationships","thaiBridge":"Keep the event facts explicit in Thai; test the relationship between a different past and its consequences.","prerequisites":["hypothetical","past-sequence"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":30,"englishPrerequisites":["hypothetical","past-sequence","first-actions","first-negatives"]},{"id":"qualification","level":"B2","order":29,"title":"Qualify and contrast ideas","family":"relationships","thaiBridge":"Understand a concession or exception, not just the nearest familiar word in a longer sentence.","prerequisites":["simple-links","relative"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":31,"englishPrerequisites":["simple-links","relative","first-actions","first-negatives"]},{"id":"professional-response","level":"B2","order":30,"title":"Handle an unexpected problem","family":"interaction","thaiBridge":"Choose by obligation, intention and politeness while keeping the guest’s problem identical.","prerequisites":["repair","possibility"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (B2); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":32,"englishPrerequisites":["repair","possibility","first-actions","first-negatives"]},{"id":"nuance","level":"C1","order":31,"title":"Implication and degrees of commitment","family":"interaction","thaiBridge":"The options should differ in intended implication or commitment, not in who or what is mentioned.","prerequisites":["professional-response","qualification"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":33,"englishPrerequisites":["professional-response","qualification","first-actions","first-negatives"]},{"id":"focus","level":"C1","order":32,"title":"Shift emphasis and information focus","family":"relationships","thaiBridge":"Thai and English can highlight information differently. Test what is foregrounded without swapping the event.","prerequisites":["relative","passive"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":34,"englishPrerequisites":["relative","passive","first-actions","first-negatives"]},{"id":"complex-time","level":"C1","order":33,"title":"Combine time and viewpoint","family":"verbs","thaiBridge":"Distinguish the speaker’s viewpoint across several events instead of assigning a single English tense to laew.","prerequisites":["future-completion","counterfactual"],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (C1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":35,"englishPrerequisites":["future-completion","counterfactual","first-actions","first-negatives"]},{"id":"first-actions","level":"A1","order":34,"title":"Who is doing it?","family":"verbs","thaiBridge":"Begin with familiar actions. Keep the action unchanged and listen for who is doing it; English be changes with the subject.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":0,"englishPrerequisites":[]},{"id":"first-negatives","level":"A1","order":35,"title":"Doing it or not?","family":"verbs","thaiBridge":"Keep the person and action fixed. Listen for not; with want and have English uses do / does not rather than placing mai before an unchanged verb.","prerequisites":[],"references":[{"sourceId":"core-inventory","locator":"Essential guide, printed pp. 10–11 (A1); focus adapted for Thai learners","status":"adapted"},{"sourceId":"english-profile","locator":"Detailed descriptor cross-check pending","status":"reference-only"}],"englishOrder":1,"englishPrerequisites":[]}]'::jsonb) v
